using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace JobWorker.Processing
{
    public interface IExpressionEngine
    {
        object Evaluate(string expression, IDictionary<string, object> context);
    }

    public class SafeExpressionEngine : IExpressionEngine
    {
        private static readonly HashSet<string> AllowedFunctions = new(StringComparer.OrdinalIgnoreCase)
        {
            "SUM", "AVG", "COUNT", "MIN", "MAX", "IF", "CONCAT", "LEN", "TRIM"
        };

        public object Evaluate(string expression, IDictionary<string, object> context)
        {
            // Production expression evaluator with sandboxing
            ValidateExpression(expression);
            return EvaluateInternal(expression, context);
        }

        private void ValidateExpression(string expression)
        {
            // Block dangerous patterns
            var tokens = Tokenize(expression);
            foreach (var token in tokens.Where(t => t.Type == TokenType.Function))
            {
                if (!AllowedFunctions.Contains(token.Value))
                    throw new SecurityException($"Function '{token.Value}' is not permitted");
            }
        }

        private object EvaluateInternal(string expr, IDictionary<string, object> ctx) => expr;
        private IEnumerable<Token> Tokenize(string expr) => 
            expr.Split(new[] { '(', ')', ',', ' ' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(s => new Token { Value = s, Type = s.All(char.IsLetter) ? TokenType.Function : TokenType.Literal });
    }

    public enum TokenType { Function, Literal, Operator }
    public class Token { public string Value { get; set; } public TokenType Type { get; set; } }

    public class UploadMetadata
    {
        public string FileName { get; set; }
        public string UserId { get; set; }
        public Dictionary<string, string> CustomFields { get; set; } = new();
        public string TransformExpression { get; set; }
    }

    public class TransformationPipeline
    {
        private readonly IExpressionEngine _engine;
        private readonly ILogger<TransformationPipeline> _logger;

        public TransformationPipeline(IExpressionEngine engine, ILogger<TransformationPipeline> logger)
        {
            _engine = engine;
            _logger = logger;
        }

        public string BuildTransformExpression(UploadMetadata metadata)
        {
            // Build expression from template + user metadata
            var template = GetTemplateForFile(metadata.FileName);
            var expression = template;

            // Substitute placeholders from custom fields
            foreach (var field in metadata.CustomFields)
            {
                var placeholder = $"{{{field.Key}}}";
                var sanitizedValue = SanitizeFieldValue(field.Value);
                expression = expression.Replace(placeholder, sanitizedValue);
            }

            return expression;
        }

        private string SanitizeFieldValue(string value)
        {
            if (string.IsNullOrWhiteSpace(value)) return "\"\"";
            // Remove dangerous characters for expression context
            var sanitized = value.Replace("\"", "").Replace("'", "").Replace(";", "");
            return $"\"{sanitized}\"";
        }

        private string GetTemplateForFile(string fileName)
        {
            var ext = Path.GetExtension(fileName)?.ToLowerInvariant();
            return ext switch
            {
                ".csv" => "CONCAT({header}, IF(LEN({delimiter}) > 0, {delimiter}, \",\"))",
                ".json" => "CONCAT({prefix}, {content})",
                _ => "CONCAT({content})"
            };
        }
    }

    public class BackgroundJobWorker
    {
        private readonly TransformationPipeline _pipeline;
        private readonly IExpressionEngine _engine;
        private readonly ILogger<BackgroundJobWorker> _logger;

        public BackgroundJobWorker(
            TransformationPipeline pipeline,
            IExpressionEngine engine,
            ILogger<BackgroundJobWorker> logger)
        {
            _pipeline = pipeline;
            _engine = engine;
            _logger = logger;
        }

        public async Task ProcessUploadAsync(UploadMetadata metadata, CancellationToken ct)
        {
            _logger.LogInformation("Processing upload {File} for user {User}", 
                metadata.FileName, metadata.UserId);

            var context = BuildEvaluationContext(metadata);

            // Phase 1: Build the transform expression from metadata
            var transformExpr = _pipeline.BuildTransformExpression(metadata);
            _logger.LogDebug("Built transform expression: {Expr}", transformExpr);

            // Phase 2: If user provided an override expression, validate and use it
            var finalExpression = MergeExpressions(transformExpr, metadata.TransformExpression);

            // Phase 3: Evaluate
            var result = _engine.Evaluate(finalExpression, context);
            _logger.LogInformation("Transform result: {Result}", result);

            await Task.CompletedTask;
        }

        private string MergeExpressions(string baseExpr, string userOverride)
        {
            if (string.IsNullOrWhiteSpace(userOverride))
                return baseExpr;

            // User override wraps the base expression for post-processing
            // The override is validated by the expression engine's allowlist
            var merged = baseExpr.Replace("$USER", userOverride);
            return merged;
        }

        private IDictionary<string, object> BuildEvaluationContext(UploadMetadata metadata)
        {
            return new Dictionary<string, object>
            {
                ["fileName"] = Path.GetFileNameWithoutExtension(metadata.FileName),
                ["userId"] = metadata.UserId,
                ["timestamp"] = DateTime.UtcNow.ToString("o")
            };
        }
    }
}
